/* IZENINFO – Espace client : globe des connexions (WebGL brut, sans dépendance).
   Points de terre : cellules de ~1° habitées (base DB-IP Lite, CC BY 4.0).
   Halos : villes des visites sur la période. Anneaux pulsants : visiteurs en ligne.
   Arcs : trajets lumineux des villes de visite vers la zone principale du site. */
(() => {
  "use strict";
  const LAND = "";
  const PI = Math.PI, RAD = PI / 180;
  const RM = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const xyz = (lat, lon, r = 1) => { const a = lat * RAD, o = lon * RAD; return [r * Math.cos(a) * Math.sin(o), r * Math.sin(a), r * Math.cos(a) * Math.cos(o)]; };
  const nf = new Intl.NumberFormat("fr-FR");
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

  /* Terre : grille ~1° atténuée pour le reste du monde, grille fine (~0,12°) et lumineuse pour la France
     métropolitaine, seule zone ciblée. Kind 0 : monde, 4 : France. */
  function land() {
    const b = atob(LAND), n = (b.length - 4) / 5, out = [];
    for (let i = 0; i < n; i++) {
      const k = 4 + i * 5, la = (b.charCodeAt(k) | b.charCodeAt(k + 1) << 8) / 100 - 90, lo = (b.charCodeAt(k + 2) | b.charCodeAt(k + 3) << 8) / 100 - 180;
      const f = b.charCodeAt(k + 4);
      out.push([la, lo, (f & 127) / 127, f & 128 ? 4 : 0]);
    }
    return out;
  }

  const VS_PT = `attribute vec3 a_p;attribute vec4 a_c;attribute vec2 a_s;
uniform mat3 u_m;uniform vec2 u_sc;uniform float u_t;uniform float u_px;uniform float u_ls;
varying vec4 v_c;varying float v_k;varying float v_ph;
void main(){vec3 p=u_m*a_p;float k=a_s.y;vec4 c=a_c;
 if(k>3.5){k=0.;}else if(k<.5){c.a*=.3;}
 if(k<.5){c.a*=mix(.1,1.,smoothstep(-.2,.25,p.z));}else{c.a*=smoothstep(-.04,.14,p.z);}
 float sz=a_s.x*(k<.5?u_ls:1.);v_ph=0.;
 if(k>1.5){v_ph=fract(u_t*.55+a_p.x*3.1+a_p.y*1.7);sz*=1.+2.4*v_ph;}
 gl_Position=vec4(p.x*u_sc.x,p.y*u_sc.y,0.,1.);
 gl_PointSize=sz*u_px*(.8+.2*max(p.z,0.));v_c=c;v_k=k;}`;
  const FS_PT = `precision mediump float;varying vec4 v_c;varying float v_k;varying float v_ph;
void main(){vec2 d=gl_PointCoord-.5;float r=length(d)*2.;if(r>1.)discard;float a;
 if(v_k<.5)a=1.-smoothstep(.45,1.,r);
 else if(v_k<1.5)a=exp(-r*r*4.)*.75+(1.-smoothstep(.16,.26,r))*.9;
 else a=smoothstep(.62,.84,r)*(1.-smoothstep(.84,1.,r))*(1.-v_ph)*1.8;
 gl_FragColor=vec4(v_c.rgb*v_c.a*a,v_c.a*a);}`;
  const VS_ARC = `attribute vec3 a_p;attribute vec3 a_q;
uniform mat3 u_m;uniform vec2 u_sc;uniform float u_t;uniform float u_px;
varying float v_a;varying float v_u;
void main(){vec3 p=u_m*a_p;float u=a_q.x;float head=fract(u_t*.28+a_q.y);float d=u-head;
 float trail=(d<=0.&&d>-.3)?pow(1.+d/.3,2.5):0.;
 float vis=clamp(max(p.z*5.+.4,(length(p.xy)-1.)*25.),0.,1.);
 v_a=vis*a_q.z*(.6+.9*trail);v_u=u;
 gl_Position=vec4(p.x*u_sc.x,p.y*u_sc.y,0.,1.);
 gl_PointSize=u_px*(2.+1.4*a_q.z+4.5*trail);}`;
  const FS_ARC = `precision mediump float;varying float v_a;varying float v_u;
void main(){float r=length(gl_PointCoord-.5)*2.;if(r>1.)discard;float a=v_a*(1.-smoothstep(.35,1.,r))*.55;
 vec3 c=mix(vec3(.62,.5,1.),vec3(.45,.9,1.),v_u);gl_FragColor=vec4(c*a,a);}`;
  const VS_BG = `attribute vec2 a_p;varying vec2 v_p;void main(){v_p=a_p;gl_Position=vec4(a_p,0.,1.);}`;
  const FS_BG = `precision mediump float;varying vec2 v_p;uniform vec2 u_sc;
void main(){vec2 q=v_p/u_sc;float r=length(q);vec4 c;
 if(r<1.){float rim=pow(r,6.);c=vec4(mix(vec3(.035,.03,.09),vec3(.2,.14,.48),rim*.8),.92);
  c.rgb+=vec3(.25,.2,.6)*pow(max(0.,1.-length(q-vec2(-.35,.4))),3.)*.18;}
 else{float g=exp(-(r-1.)*9.);c=vec4(vec3(.36,.3,1.)*g*.5,g*.5);}
 gl_FragColor=vec4(c.rgb*c.a,c.a);}`;

  function prog(gl, vs, fs) {
    const p = gl.createProgram();
    for (const [t, s] of [[gl.VERTEX_SHADER, vs], [gl.FRAGMENT_SHADER, fs]]) {
      const sh = gl.createShader(t); gl.shaderSource(sh, s); gl.compileShader(sh);
      if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(sh));
      gl.attachShader(p, sh);
    }
    gl.linkProgram(p);
    if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(p));
    const loc = {};
    const na = gl.getProgramParameter(p, gl.ACTIVE_ATTRIBUTES), nu = gl.getProgramParameter(p, gl.ACTIVE_UNIFORMS);
    for (let i = 0; i < na; i++) { const n = gl.getActiveAttrib(p, i).name; loc[n] = gl.getAttribLocation(p, n); }
    for (let i = 0; i < nu; i++) { const n = gl.getActiveUniform(p, i).name; loc[n] = gl.getUniformLocation(p, n); }
    return { p, loc };
  }

  function mat(yaw, pitch) {
    const cy = Math.cos(yaw), sy = Math.sin(yaw), cp = Math.cos(pitch), sp = Math.sin(pitch);
    /* M = Rx(pitch)·Ry(yaw), en colonnes pour WebGL */
    return new Float32Array([cy, sp * sy, -cp * sy, 0, cp, sp, sy, -sp * cy, cp * cy]);
  }
  const apply = (m, v) => [m[0] * v[0] + m[3] * v[1] + m[6] * v[2], m[1] * v[0] + m[4] * v[1] + m[7] * v[2], m[2] * v[0] + m[5] * v[1] + m[8] * v[2]];

  function create(root) {
    const cv = root.querySelector("canvas"), tip = root.querySelector(".gtip");
    const labBox = document.createElement("div"); labBox.className = "glabs"; labBox.setAttribute("aria-hidden", "true"); root.insertBefore(labBox, tip);
    let labs = [];
    const gl = cv.getContext("webgl", { antialias: true, alpha: true, premultipliedAlpha: true });
    if (!gl) { root.classList.add("nogl"); return null; }
    let PT, ARC, BG;
    try { PT = prog(gl, VS_PT, FS_PT); ARC = prog(gl, VS_ARC, FS_ARC); BG = prog(gl, VS_BG, FS_BG); }
    catch (e) { root.classList.add("nogl"); return null; }
    const bPt = gl.createBuffer(), bArc = gl.createBuffer(), bBg = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, bBg); gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
    const LANDPTS = land();
    let nPt = 0, nArc = 0;
    let period = [], live = [], hub = null, marks = [];
    let yaw = -2.4 * RAD, pitch = 46.4 * RAD, vy = 0, vp = 0, zoom = 10, zoomT = 10;
    let target = null, idleAt = 0, drag = null, t0 = performance.now(), last = t0, raf = 0, visible = true, W = 0, H = 0, R = 0, dpr = 1;

    function build() {
      const f = [];
      const P = (v, r, g, b, a, s, k) => f.push(v[0], v[1], v[2], r, g, b, a, s, k);
      for (const [la, lo, v, k] of LANDPTS) k === 4 ? P(xyz(la, lo), .52 + .1 * v, .52 + .3 * v, 1, .38 + .45 * v, 1.8 + 1.1 * v, 4)
        : P(xyz(la, lo), .5, .44, 1, .3 + .4 * v, 1.4 + .8 * v, 0);
      marks = [];
      const max = period.reduce((m, c) => Math.max(m, c.n), 1);
      for (const c of period) {
        const q = Math.sqrt(c.n / max), v = xyz(c.lat, c.lon, 1.003);
        P(v, .62 - .2 * q, .55 + .38 * q, 1, .8 + .2 * q, 11 + 30 * q, 1);
        marks.push({ v, c, kind: "p" });
      }
      for (const c of live) {
        const v = xyz(c.lat, c.lon, 1.005);
        P(v, 1, 1, 1, 1, 10, 1);
        P(v, .55, .95, 1, 1, 22, 2);
        marks.push({ v, c, kind: "l" });
      }
      if (hub) { P(xyz(hub.lat, hub.lon, 1.006), 1, .95, 1, 1, 12, 1); P(xyz(hub.lat, hub.lon, 1.006), .75, .6, 1, .7, 30, 2); }
      /* Étiquettes : les villes principales et celles en ligne */
      const seen = new Set(), L = [];
      for (const c of live.concat(period.slice(0, 7))) {
        const key = c.lat + "," + c.lon; if (seen.has(key)) continue; seen.add(key);
        const isLive = live.some(x => x.lat === c.lat && x.lon === c.lon), inP = period.find(x => x.lat === c.lat && x.lon === c.lon);
        L.push({ v: xyz(c.lat, c.lon), name: String(c.name).split(" · ")[0], n: inP ? inP.n : 0, live: isLive });
      }
      L.sort((a, b) => b.n - a.n || (b.live ? 1 : 0) - (a.live ? 1 : 0)); /* la zone principale d'abord */
      labBox.textContent = "";
      labs = L.map(l => { const d = document.createElement("span"); d.className = "glab" + (l.live ? " on" : "");
        d.innerHTML = `${esc(l.name)}${l.n ? ` <i>${nf.format(l.n)}</i>` : ""}`; labBox.appendChild(d); return { ...l, el: d }; });
      nPt = f.length / 9;
      gl.bindBuffer(gl.ARRAY_BUFFER, bPt); gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(f), gl.STATIC_DRAW);

      const a = [];
      if (hub) {
        const H3 = xyz(hub.lat, hub.lon);
        const arcs = period.filter(c => c !== hub).slice(0, 14).map(c => [c, .7]).concat(live.map(c => [c, 1.3]));
        arcs.forEach(([c, w], i) => {
          const A = xyz(c.lat, c.lon), dot = Math.min(1, Math.max(-1, A[0] * H3[0] + A[1] * H3[1] + A[2] * H3[2])), om = Math.acos(dot);
          if (om < .004) return;
          const so = Math.sin(om), lift = Math.min(.42, .06 + om * .3), ph = (i * .137 + c.lat * .01) % 1, N = Math.max(60, Math.round(om * 1600));
          for (let s = 0; s <= N; s++) {
            const u = s / N, k1 = Math.sin((1 - u) * om) / so, k2 = Math.sin(u * om) / so, h = 1 + lift * Math.sin(PI * u);
            const p = [(A[0] * k1 + H3[0] * k2) * h, (A[1] * k1 + H3[1] * k2) * h, (A[2] * k1 + H3[2] * k2) * h, u, ph, w];
            a.push(...p);
          }
        });
      }
      nArc = a.length / 6;
      gl.bindBuffer(gl.ARRAY_BUFFER, bArc); gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(a.length ? a : [0, 0, 0, 0, 0, 0]), gl.STATIC_DRAW);
    }

    function size() {
      dpr = Math.min(devicePixelRatio || 1, 2);
      const r = cv.getBoundingClientRect(); W = r.width; H = r.height;
      cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
      gl.viewport(0, 0, cv.width, cv.height);
    }

    function frame(now) {
      raf = 0;
      const dt = Math.min(50, now - last); last = now;
      if (target) {
        let dy = target.yaw - yaw; dy = Math.atan2(Math.sin(dy), Math.cos(dy));
        yaw += dy * .06; pitch += (target.pitch - pitch) * .06;
        if (Math.abs(dy) < .002 && Math.abs(target.pitch - pitch) < .002) target = null;
      } else if (!drag) {
        yaw += vy; pitch += vp; vy *= .94; vp *= .94;
        /* Pas de rotation automatique : la vue reste sur la France. */
      }
      pitch = Math.max(-1.25, Math.min(1.25, pitch));
      zoom += (zoomT - zoom) * .15;
      R = Math.min(W, H) * .43 * zoom;
      const sc = [R / (W / 2), R / (H / 2)], m = mat(yaw, pitch), t = RM ? 0 : (now - t0) / 1000;
      gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      gl.useProgram(BG.p); gl.uniform2fv(BG.loc.u_sc, sc);
      gl.bindBuffer(gl.ARRAY_BUFFER, bBg); gl.enableVertexAttribArray(BG.loc.a_p); gl.vertexAttribPointer(BG.loc.a_p, 2, gl.FLOAT, false, 0, 0);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4); gl.disableVertexAttribArray(BG.loc.a_p);
      gl.blendFunc(gl.ONE, gl.ONE);
      if (nArc) {
        gl.useProgram(ARC.p); gl.uniformMatrix3fv(ARC.loc.u_m, false, m); gl.uniform2fv(ARC.loc.u_sc, sc); gl.uniform1f(ARC.loc.u_t, t);
        gl.bindBuffer(gl.ARRAY_BUFFER, bArc);
        gl.enableVertexAttribArray(ARC.loc.a_p); gl.vertexAttribPointer(ARC.loc.a_p, 3, gl.FLOAT, false, 24, 0);
        gl.enableVertexAttribArray(ARC.loc.a_q); gl.vertexAttribPointer(ARC.loc.a_q, 3, gl.FLOAT, false, 24, 12);
        gl.uniform1f(ARC.loc.u_px, dpr * Math.max(.8, Math.min(1.4, R / 2000)));
        gl.drawArrays(gl.POINTS, 0, nArc);
        gl.disableVertexAttribArray(ARC.loc.a_p); gl.disableVertexAttribArray(ARC.loc.a_q);
      }
      gl.useProgram(PT.p); gl.uniformMatrix3fv(PT.loc.u_m, false, m); gl.uniform2fv(PT.loc.u_sc, sc); gl.uniform1f(PT.loc.u_t, t); gl.uniform1f(PT.loc.u_px, dpr * 1.5);
      gl.uniform1f(PT.loc.u_ls, Math.max(.45, Math.min(1.4, R / 2400)));
      gl.bindBuffer(gl.ARRAY_BUFFER, bPt);
      gl.enableVertexAttribArray(PT.loc.a_p); gl.vertexAttribPointer(PT.loc.a_p, 3, gl.FLOAT, false, 36, 0);
      gl.enableVertexAttribArray(PT.loc.a_c); gl.vertexAttribPointer(PT.loc.a_c, 4, gl.FLOAT, false, 36, 12);
      gl.enableVertexAttribArray(PT.loc.a_s); gl.vertexAttribPointer(PT.loc.a_s, 2, gl.FLOAT, false, 36, 28);
      gl.drawArrays(gl.POINTS, 0, nPt);
      gl.disableVertexAttribArray(PT.loc.a_p); gl.disableVertexAttribArray(PT.loc.a_c); gl.disableVertexAttribArray(PT.loc.a_s);
      if (tip.dataset.k) placeTip();
      placeLabels();
      loop();
    }
    function placeLabels() {
      const m = mat(yaw, pitch), taken = [];
      for (const l of labs) {
        const p = apply(m, l.v), x = W / 2 + p[0] * R, y = H / 2 - p[1] * R;
        const ok = p[2] > .08 && x > 30 && x < W - 30 && y > 14 && y < H - 10 && !taken.some(t => Math.abs(t[0] - x) < 90 && Math.abs(t[1] - y) < 22);
        l.el.style.opacity = ok ? "1" : "0";
        if (ok) { taken.push([x, y]); const left = x > W - 130; l.el.style.transform = `translate(${Math.round(left ? x - 14 - l.el.offsetWidth : x + 14)}px,${Math.round(y - 9)}px)`; }
      }
    }
    let paused = false;
    function loop() { if (!raf && visible && !paused && !document.hidden && W > 20 && H > 20) raf = requestAnimationFrame(frame); }

    /* Survol : ville la plus proche du pointeur */
    let hover = null;
    function project(v) { const p = apply(mat(yaw, pitch), v); return { x: W / 2 + p[0] * R, y: H / 2 - p[1] * R, z: p[2] }; }
    function pick(x, y) {
      let best = null, bd = 18 * 18;
      for (const mk of marks) {
        const p = project(mk.v); if (p.z < .08) continue;
        const d = (p.x - x) ** 2 + (p.y - y) ** 2;
        if (d < bd || (best && d === bd && mk.kind === "l")) { bd = d; best = mk; }
      }
      return best;
    }
    function placeTip() {
      if (!hover) return;
      const p = project(hover.v);
      if (p.z < .08) { hideTip(); return; }
      /* L'info-bulle reste entière dans le cadre, quelle que soit la taille d'écran */
      const hw = tip.offsetWidth / 2, below = p.y - tip.offsetHeight - 18 < 0;
      tip.classList.toggle("below", below);
      tip.style.transform = `translate(${Math.round(Math.min(W - hw - 6, Math.max(hw + 6, p.x)))}px,${Math.round(p.y)}px)`;
    }
    function showTip(mk) {
      hover = mk;
      const name = mk.c.name, inP = period.find(c => c.name === name || (c.lat === mk.c.lat && c.lon === mk.c.lon)), inL = live.find(c => c.lat === mk.c.lat && c.lon === mk.c.lon);
      tip.innerHTML = `<b>${esc(name)}</b>` + (inP ? `<span>${nf.format(inP.n)} visite${inP.n > 1 ? "s" : ""} sur la période</span>` : "") +
        (inL ? `<span class="on">${nf.format(inL.n)} en ligne maintenant</span>` : "") + (hub && hub.lat === mk.c.lat && hub.lon === mk.c.lon ? `<span>Zone principale</span>` : "");
      tip.dataset.k = "1"; tip.hidden = false; placeTip();
    }
    function hideTip() { hover = null; tip.hidden = true; delete tip.dataset.k; }

    /* Zoom tactile à deux doigts, pincement du pavé tactile (Ctrl + molette) et double-clic */
    const ptr = new Map(); let pinch = null;
    const dist = () => { const [a, b] = [...ptr.values()]; return Math.hypot(a.x - b.x, a.y - b.y) || 1; };
    const setZoom = z => { zoomT = Math.max(.8, Math.min(40, z)); userZoom = true; idleAt = performance.now(); loop(); };
    cv.addEventListener("pointerdown", e => { ptr.set(e.pointerId, { x: e.clientX, y: e.clientY }); if (ptr.size === 2) { pinch = { d0: dist(), z0: zoomT }; drag = null; hideTip(); } }, true);
    cv.addEventListener("pointermove", e => {
      if (!ptr.has(e.pointerId)) return;
      ptr.set(e.pointerId, { x: e.clientX, y: e.clientY });
      if (pinch && ptr.size === 2) { setZoom(pinch.z0 * dist() / pinch.d0); zoom = zoomT; e.stopImmediatePropagation(); }
    }, true);
    const pend = e => { ptr.delete(e.pointerId); if (ptr.size < 2) pinch = null; };
    cv.addEventListener("pointerup", pend, true); cv.addEventListener("pointercancel", pend, true);
    cv.addEventListener("wheel", e => { if (!e.ctrlKey) return; e.preventDefault(); setZoom(zoomT * Math.exp(-e.deltaY * .01)); }, { passive: false });
    cv.addEventListener("dblclick", () => setZoom(zoomT * 1.6));

    cv.addEventListener("pointerdown", e => {
      if (pinch) return;
      drag = { x: e.clientX, y: e.clientY, sx: e.clientX, sy: e.clientY, id: e.pointerId, t: performance.now() };
      target = null; vy = vp = 0; idleAt = performance.now();
      if (e.pointerType !== "touch") cv.setPointerCapture(e.pointerId);
      cv.classList.add("grab");
    });
    cv.addEventListener("pointermove", e => {
      const r = cv.getBoundingClientRect(), x = e.clientX - r.left, y = e.clientY - r.top;
      if (drag && drag.id === e.pointerId) {
        const dx = e.clientX - drag.x, dy = e.clientY - drag.y, k = .0055 / zoom;
        yaw += dx * k; pitch += dy * k; vy = dx * k * .6; vp = dy * k * .6;
        drag.x = e.clientX; drag.y = e.clientY; idleAt = performance.now(); hideTip(); return;
      }
      if (e.pointerType === "mouse") { const mk = pick(x, y); if (mk) showTip(mk); else hideTip(); cv.style.cursor = mk ? "pointer" : ""; }
    });
    const up = e => {
      if (!drag) return;
      const moved = Math.hypot(e.clientX - drag.sx, e.clientY - drag.sy);
      if (moved < 6) { const r = cv.getBoundingClientRect(), mk = pick(e.clientX - r.left, e.clientY - r.top); if (mk) showTip(mk); else hideTip(); }
      drag = null; cv.classList.remove("grab"); idleAt = performance.now();
    };
    cv.addEventListener("pointerup", up); cv.addEventListener("pointercancel", () => { drag = null; cv.classList.remove("grab"); });
    cv.addEventListener("pointerleave", e => { if (e.pointerType === "mouse" && !drag) hideTip(); });
    root.querySelectorAll("[data-gz]").forEach(b => b.addEventListener("click", () => {
      const k = b.dataset.gz; idleAt = performance.now();
      if (k === "in") { zoomT = Math.min(40, zoomT * 1.5); userZoom = true; }
      else if (k === "out") { zoomT = Math.max(.8, zoomT / 1.5); userZoom = true; }
      else focus();
      loop();
    }));

    /* Vue cible : la France métropolitaine, cadrée dans le globe. */
    const FR = { lat: 46.4, lon: 2.4 };
    /* Zoom qui fait tenir la France (~0,16 rad de haut comme de large) dans le cadre. */
    const fit = () => Math.max(1, Math.min(5.0 * H, 5.4 * W) / (Math.min(W, H) * .43));
    let userZoom = false;
    function focus() { target = { yaw: -FR.lon * RAD, pitch: FR.lat * RAD }; zoomT = fit(); userZoom = false; }

    new ResizeObserver(() => { size(); if (W < 20 || H < 20) return; if (!userZoom) zoom = zoomT = fit(); loop(); }).observe(cv);
    new IntersectionObserver(es => { visible = es[0].isIntersecting; loop(); }).observe(root);
    document.addEventListener("visibilitychange", loop);
    size(); build();

    let sigP = "", sigL = "";
    return {
      /* Carte réduite : plus aucun calcul tant qu'elle n'est pas rouverte */
      pause(v) { paused = !!v; if (!paused) { size(); if (!userZoom && W > 20 && H > 20) zoom = zoomT = fit(); loop(); } },
      setPeriod(geo) {
        const s = JSON.stringify(geo || []); if (s === sigP) return; sigP = s;
        period = (geo || []).slice().sort((a, b) => b.n - a.n);
        hub = period[0] || null;
        build(); if (hover) showTip(hover); loop();
      },
      setLive(geo) {
        const s = JSON.stringify(geo || []); if (s === sigL) return; sigL = s;
        live = geo || [];
        build(); if (hover) showTip(hover); loop();
      }
    };
  }

  window.IZGlobe = { create, land };
})();
